// Check if brackets are balanced in the input string.
// Brackets: ( ) [ ] { }
// Ignore brackets inside double-quoted strings "...".
// Backslash escapes inside strings: \" does not end the string.
// Returns true if balanced, false otherwise.
bool brackets_balanced(const std::string& text) {

