    if (c == '"') { in_str = true; continue; }
    if (c=='('||c=='['||c=='{') stk.push(c);
    else if (c==')'||c==']'||c=='}') {
        if (stk.empty()) return false; char t=stk.top(); stk.pop();
        if ((c==')'&&t!='(')||(c==']'&&t!='[')||(c=='}'&&t!='{')) return false;
