#include <string>
#include <map>
#include <cassert>
#include <sstream>

// Parse INI-style config text.  Returns a nested map: section -> key -> value.
//
// Rules:
// - Lines starting with '#' or ';' are comments (after trimming leading spaces).
// - "[section]" starts a new section.
// - "key = value" adds a key-value pair to the current section.
// - Leading/trailing whitespace on keys and values is trimmed.
// - Section names can contain '.' for hierarchy: "[parent.child]".
//   A child section INHERITS all keys from its parent section that it doesn't
//   override.  E.g. if [db] has host=localhost and [db.prod] has port=5432,
//   then [db.prod] has BOTH host=localhost AND port=5432.
// - The global (unnamed) section is stored under the key "".
// - Inheritance is ONLY one level deep: "a.b" inherits from "a", but NOT
//   from "" (global).

using IniMap = std::map<std::string, std::map<std::string, std::string>>;

IniMap parse_ini(const std::string& text) {

golden_completion:
IniMap result; std::string section; std::istringstream stream(text); std::string line;
auto trim=[](std::string s){size_t a=s.find_first_not_of(" \t"),b=s.find_last_not_of(" \t");return a==std::string::npos?"":s.substr(a,b-a+1);};
while (std::getline(stream, line)) {
    std::string t = trim(line); if (t.empty()||t[0]=='#'||t[0]==';') continue;
    if (t[0]=='[') { section=t.substr(1,t.find(']')-1); }
    else { auto eq=t.find('='); if(eq==std::string::npos)continue; result[section][trim(t.substr(0,eq))]=trim(t.substr(eq+1)); }
}
for (auto& [sec,kv]:result) { auto d=sec.rfind('.'); if(d!=std::string::npos) { auto p=sec.substr(0,d); if(result.count(p)) for(auto&[pk,pv]:result[p]) if(!kv.count(pk)) kv[pk]=pv; } }
return result;

suffix:
}

int main() {
    std::string ini = R"(
# Database config
[db]
host = localhost
port = 3306

[db.prod]
port = 5432

[db.staging]
host = staging.local
)";
    auto cfg = parse_ini(ini);
    // [db.prod] inherits host from [db], overrides port
    assert(cfg["db.prod"]["host"] == "localhost");
    assert(cfg["db.prod"]["port"] == "5432");
    // [db.staging] inherits port from [db], overrides host
    assert(cfg["db.staging"]["port"] == "3306");
    assert(cfg["db.staging"]["host"] == "staging.local");
    // [db] is unchanged
    assert(cfg["db"]["host"] == "localhost");
    assert(cfg["db"]["port"] == "3306");
    return 0;
}

