// Parse structured log text into entries.
// - Log line: "[TIMESTAMP] LEVEL: message"
// - Line starting with 4+ spaces is continuation: append to previous
//   entry's message with a newline character (trim leading spaces).
// - # comments and blank lines are ignored (NOT continuations).
std::vector<LogEntry> parseLogs(const std::string& text) {
    std::vector<LogEntry> entries;
    std::istringstream stream(text);
