        entries.back().message += "\n" + line.substr(s); continue;
    }
    if (line[0] != '[') continue;
    size_t cb = line.find(']'); if (cb == std::string::npos) continue;
    size_t ls = cb+1; while (ls < line.size() && line[ls]==' ') ls++;
