// group_consecutive: Group consecutive equal elements together.
// Like Python's itertools.groupby -- elements are grouped by ADJACENCY,
// not by global uniqueness. The same key can appear in multiple groups.
// Uses the provided comparator for equality.
// Returns vector of pairs: (first_element_of_run, vector_of_elements).
template<typename T, typename Eq>
std::vector<std::pair<T, std::vector<T>>> groupConsecutive(
    const std::vector<T>& data, Eq eq) {

golden_completion:
std::vector<std::pair<T, std::vector<T>>> groups;
if (data.empty()) return groups;
T key = data[0];
std::vector<T> cur = {data[0]};
for (size_t i = 1; i < data.size(); i++) {
    if (eq(key, data[i])) { cur.push_back(data[i]); }
    else { groups.push_back({key, cur}); key = data[i]; cur = {data[i]}; }
}
groups.push_back({key, cur});
return groups;

suffix:
}

int main() {
    std::vector<int> v = {1, 1, 2, 2, 2, 1, 1, 3};
    auto g = groupConsecutive(v, [](int a, int b){ return a == b; });
    assert(g.size() == 4);  // [1,1], [2,2,2], [1,1], [3] -- NOT 3 groups!
    assert(g[0].first == 1 && g[0].second.size() == 2);
    assert(g[1].first == 2 && g[1].second.size() == 3);
    assert(g[2].first == 1 && g[2].second.size() == 2);
    assert(g[3].first == 3 && g[3].second.size() == 1);

