    assert(r1[1] == std::make_pair(2, 20));
    assert(r1[2] == std::make_pair(3, 20));  // 20 repeated, NOT 0

    auto r2 = zipExtend(std::vector<int>{5}, std::vector<int>{1, 2, 3, 4});
    assert(r2.size() == 4);
    assert(r2[3] == std::make_pair(5, 4));  // 5 repeated

    auto r3 = zipExtend(std::vector<int>{}, std::vector<int>{1});
    assert(r3.empty());  // empty input -> empty output
    std::cout << "OK" << std::endl;
