for (size_t i = 0; i < data.size(); i++) indexed.push_back({data[i], i});
std::vector<std::pair<T, size_t>> uniq;
for (auto& p : indexed) { bool dup = false; for (auto& u : uniq) if (eq(p.first, u.first)) { dup = true; break; } if (!dup) uniq.push_back(p); }
std::sort(uniq.begin(), uniq.end(), [&](auto& a, auto& b) { return less(a.first, b.first) || (!less(b.first, a.first) && a.second < b.second); });
std::vector<T> res; for (auto& p : uniq) res.push_back(p.first);
return res;

suffix:
}

