// slidingWindowMaxCircular: Maximum in each sliding window of size k,
// treating data as CIRCULAR (wraps around after last element).
// Result has exactly data.size() elements.
// Window at position i: data[i], data[(i+1)%n], ..., data[(i+k-1)%n].
// If k >= n, every window sees all elements, so result is all global max.
// k must be >= 1. Empty data returns empty.
std::vector<int> slidingWindowMaxCircular(const std::vector<int>& data, int k) {

golden_completion:
int n = data.size(); if (n == 0) return {};
if (k >= n) { int mx = *std::max_element(data.begin(), data.end()); return std::vector<int>(n, mx); }
std::vector<int> ext(2*n); for (int i = 0; i < 2*n; i++) ext[i] = data[i%n];
std::deque<int> dq; std::vector<int> result;
for (int i = 0; i < n+k-1; i++) {
    while (!dq.empty() && ext[dq.back()] <= ext[i]) dq.pop_back();
    dq.push_back(i); if (dq.front() <= i-k) dq.pop_front();
    if (i >= k-1 && (int)result.size() < n) result.push_back(ext[dq.front()]);
}
return result;

suffix:
}

int main() {
    auto r = slidingWindowMaxCircular({1, 3, 2, 5, 4}, 3);
    assert(r == std::vector<int>({3, 5, 5, 5, 4}));

    auto r2 = slidingWindowMaxCircular({5, 1, 3}, 1);
    assert(r2 == std::vector<int>({5, 1, 3}));

    auto r3 = slidingWindowMaxCircular({2, 7, 1}, 3);
    assert(r3 == std::vector<int>({7, 7, 7}));

    auto r4 = slidingWindowMaxCircular({}, 2);
    assert(r4.empty());
    std::cout << "OK" << std::endl;
    return 0;
