// SSH config parser (~/.ssh/config style):
// "Host <pattern>" starts a new host block
// Following "Key value" lines belong to that block
// Lines before any Host belong to "*" (default)
// '#' lines are comments, blank lines ignored
// Keys are case-insensitive (stored lowercase)
// Returns: map<host_pattern, map<key, value>>

std::string to_lower(const std::string& s) {
    std::string r = s; for (auto& c : r) c = (c>='A'&&c<='Z') ? c+32 : c; return r;
}
std::string trim_ws(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r");
    if (a == std::string::npos) return "";
    return s.substr(a, s.find_last_not_of(" \t\r") - a + 1);
