        std::string line = strip_str(raw);
        if (line.empty()||line.substr(0,2)=="//") continue;
        if (line.size()>=8&&line.substr(0,8)=="#define ") {
            auto [n,md]=parse_one_define(strip_str(line.substr(8))); result[n]=md;
        } else if (line.size()>=7&&line.substr(0,7)=="#undef ") result.erase(strip_str(line.substr(7)));
    } return result;
}

