            cum += weights[j];
            if (r < cum) {
                result.push_back(items[j]);
                break;
            }
        }
    }
    return result;
}
std::vector<std::string> weighted_random_select(const std::vector<std::string>& items,
                                                 const std::vector<double>& weights,
                                                 size_t n,
                                                 LCG& rng) {
    std::vector<std::string> result;
    result.reserve(n);
    double total = std::accumulate(weights.begin(), weights.end(), 0.0);
    for (size_t i = 0; i < n; ++i) {
        double r = rng.next() * total;
        double cum = 0.0;
        for (size_t j = 0; j < items.size(); ++j) {
            cum += weights[j];
            if (r < cum) {
                result.push_back(items[j]);
                break;
            }
        }
    }
    return result;
}
